import{_ as i,a0 as d,w as s,s as p,I as t,x as r,a1 as a,A as o,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"在 Fedora 中使用 FreeMind 介绍你自己 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 中使用 FreeMind 介绍你自己 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 中使用 FreeMind 介绍你自己 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 中使用 FreeMind 介绍你自己 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190123 Mind map yourself using FreeMind and Fedora","title":"在 Fedora 中使用 FreeMind 介绍你自己","tag":"201903","desc":""},"relativePath":"201903/20190123 Mind map yourself using FreeMind and Fedora.md","filePath":"[post].md"}'),f={name:"201903/20190123 Mind map yourself using FreeMind and Fedora.md"};function m(u,e,g,F,M,x){const n=d("Link");return s(),p("div",null,[e[24]||(e[24]=t("h1",{id:"在-fedora-中使用-freemind-介绍你自己",tabindex:"-1"},[r("在 Fedora 中使用 FreeMind 介绍你自己 "),t("a",{class:"header-anchor",href:"#在-fedora-中使用-freemind-介绍你自己","aria-label":"Permalink to “在 Fedora 中使用 FreeMind 介绍你自己”"},"​")],-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/01/freemind-816x345.jpg",alt:""})],-1)),t("p",null,[e[1]||(e[1]=r("介绍你自己的思维导图，一开始听起来有些牵强。它是关于神经通路么？还是心灵感应？完全不是。相反，自己的思维导图是一种在视觉上向他人描述自己的方式。它还展示了你拿来描述自己的特征之间的联系。这是一种以聪明又同时可控的与他人分享信息的有用方式。你可以使用任何思维导图应用来做到。本文向你展示如何使用 Fedora 中提供的 ",-1)),a(n,{href:"http://freemind.sourceforge.net/wiki/index.php/Main_Page"},{default:o(()=>[...e[0]||(e[0]=[r("FreeMind",-1)])]),_:1}),e[2]||(e[2]=r("。",-1))]),e[26]||(e[26]=t("h3",{id:"获取应用",tabindex:"-1"},[r("获取应用 "),t("a",{class:"header-anchor",href:"#获取应用","aria-label":"Permalink to “获取应用”"},"​")],-1)),t("p",null,[e[4]||(e[4]=r("FreeMind 已经出现有一段时间了。虽然 UI 有点过时，应该做一些更新了，但它是一个功能强大的应用，提供了许多构建思维导图的选项。当然，它是 100％ 开源的。还有其他思维导图应用可供 Fedora 和 Linux 用户使用。查看",-1)),a(n,{href:"https://fedoramagazine.org/three-mind-mapping-tools-fedora/"},{default:o(()=>[...e[3]||(e[3]=[r("此前一篇涵盖多个思维导图选择的文章",-1)])]),_:1}),e[5]||(e[5]=r("。",-1))]),t("p",null,[e[7]||(e[7]=r("如果你运行的是 Fedora Workstation，请使用“软件”应用从 Fedora 仓库安装 FreeMind。或者在终端中使用这个 ",-1)),a(n,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:o(()=>[...e[6]||(e[6]=[r("sudo",-1)])]),_:1}),e[8]||(e[8]=r(" 命令：",-1))]),e[27]||(e[27]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install freemind</span></span></code></pre></div><p>你可以从 Fedora Workstation 中的 GNOME Shell Overview 启动应用。或者使用桌面环境提供的应用启动服务。默认情况下，FreeMind 会显示一个新的空白脑图：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-17-04-1024x736.png" alt=""></p><p><em>FreeMind 初始（空白）思维导图</em></p><p>脑图由链接的项目或描述（节点）组成。当你想到与节点相关的内容时，只需创建一个与其连接的新节点即可。</p><h3 id="做你自己的脑图" tabindex="-1">做你自己的脑图 <a class="header-anchor" href="#做你自己的脑图" aria-label="Permalink to “做你自己的脑图”">​</a></h3><p>单击初始节点。编辑文本并按回车将其替换为你的姓名。你就能开始你的思维导图。</p><p>如果你必须向某人充分描述自己，你会怎么想？可能会有很多东西。你平时做什么？你喜欢什么？你不喜欢什么？你有什么价值？你有家庭吗？所有这些都可以在节点中体现。</p><p>要添加节点连接，请选择现有节点，然后单击“Insert”，或使用“灯泡”图标作为新的子节点。要在与新子级相同的层级添加另一个节点，请使用回车。</p><p>如果你弄错了，别担心。你可以使用 <code>Delete</code> 键删除不需要的节点。内容上没有规则。但是最好是短节点。它们能让你在创建导图时思维更快。简洁的节点还能让其他浏览者更轻松地查看和理解。</p><p>该示例使用节点规划了每个主要类别：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-32-38-1024x736.png" alt=""></p><p><em>个人思维导图，第一级</em></p><p>你可以为这些区域中的每个区域另外迭代一次。让你的思想自由地连接想法以生成导图。不要担心“做得正确“。最好将所有内容从头脑中移到显示屏上。这是下一级导图的样子。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/01/Screenshot-from-2019-01-19-15-38-00-1024x736.png" alt=""></p><p><em>个人思维导图，第二级</em></p><p>你可以以相同的方式扩展任何这些节点。请注意你在示例中可以了解多少有关 “John Q. Public” 的信息。</p><h3 id="如何使用你的个人思维导图" tabindex="-1">如何使用你的个人思维导图 <a class="header-anchor" href="#如何使用你的个人思维导图" aria-label="Permalink to “如何使用你的个人思维导图”">​</a></h3><p>这是让团队或项目成员互相介绍的好方法。你可以将各种格式和颜色应用于导图以赋予其个性。当然，这些在纸上做很有趣。但是在 Fedora 中安装一个就意味着你可以随时修复错误，甚至可以在你改变的时候做出修改。</p><p>祝你在探索个人思维导图上玩得开心！</p><hr>',21)),t("p",null,[e[10]||(e[10]=r("via: ",-1)),a(n,{href:"https://fedoramagazine.org/mind-map-yourself-using-freemind-and-fedora/"},{default:o(()=>[...e[9]||(e[9]=[r("https://fedoramagazine.org/mind-map-yourself-using-freemind-and-fedora/",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=r("作者：",-1)),a(n,{href:"https://fedoramagazine.org/author/pfrields/"},{default:o(()=>[...e[11]||(e[11]=[r("Paul W. Frields",-1)])]),_:1}),e[16]||(e[16]=r(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[12]||(e[12]=[r("lujun9972",-1)])]),_:1}),e[17]||(e[17]=r(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:o(()=>[...e[13]||(e[13]=[r("geekpi",-1)])]),_:1}),e[18]||(e[18]=r(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[14]||(e[14]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[21]||(e[21]=r("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[19]||(e[19]=[r("LCTT",-1)])]),_:1}),e[22]||(e[22]=r(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...e[20]||(e[20]=[r("Linux中国",-1)])]),_:1}),e[23]||(e[23]=r(" 荣誉推出",-1))])])}const h=i(f,[["render",m]]);export{b as __pageData,h as default};
